fn validate_email(email: Str) -> Result[Str, Str] {
  if email.len() == 0 {
    return Err("email is empty — please provide an email address");
  }
  if !email.contains("@") {
    return Err("email '" + email + "' is missing '@' symbol — example: user@domain.com");
  }
  if !email.contains(".") {
    return Err("email '" + email + "' is missing domain — example: user@domain.com");
  }
  return Ok(email);
}

fn main() -> Int {
  match validate_email("user@domain.com") {
    Ok(_) => return 1,
    Err(_) => return 0,
  }
}
